#!/usr/bin/env node
/**
 * Builds v2/bundle.css -- every v2 sheet concatenated, in one file.
 *
 * WHY: a consumer linking the sheets individually pays a render-blocking
 * request per sheet, and the browser paints nothing until the SLOWEST one
 * lands. Cowork was loading twelve. Measured warm from Thailand, the slowest
 * of those twelve answered in 0.84s.
 *
 * WHY CONCATENATION AND NOT SOMETHING CLEVERER:
 *  - `@import` inside one sheet is worse, not better: the browser cannot even
 *    discover the imports until the outer file has arrived, so the requests
 *    serialise instead of running in parallel.
 *  - jsDelivr's /combine/ endpoint serves many files as one response, but the
 *    combined URL sits at a DIFFERENT path, and shell.css and form-bar.css both
 *    reference url("./assets/ccd-mark-full.svg"). A mask whose URL resolves to
 *    nothing renders an EMPTY BOX and logs no error -- the logo would vanish
 *    silently. The bundle therefore has to live in v2/, beside the assets.
 *
 * WHY CONCATENATION IS SAFE HERE: no sheet contains @import, @charset or
 * @layer, so the cascade is decided purely by source order -- and source order
 * is exactly what concatenation preserves. Checked before writing this file;
 * `--check` re-checks it on every run rather than trusting this comment.
 *
 * ORDER: tokens, type, then alphabetical. That is a superset of the order
 * cowork already linked, with its twelve sheets in unchanged RELATIVE order, so
 * the bundle cannot cascade differently from what shipped before it.
 *
 * Usage:
 *   node v2/build-bundle.mjs           # write v2/bundle.css
 *   node v2/build-bundle.mjs --check   # exit 1 if bundle.css is stale
 *
 * Run it before cutting a tag. A stale bundle is the failure mode to fear:
 * every consumer would keep rendering the previous release while the source
 * files show the new one, and nothing would error.
 */
import { readFileSync, writeFileSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const V2 = dirname(fileURLToPath(import.meta.url));
const OUT = 'bundle.css';
const FIRST = ['tokens.css', 'type.css'];   // variables and the type scale lead

const all = readdirSync(V2).filter((f) => f.endsWith('.css') && f !== OUT).sort();
const order = [...FIRST, ...all.filter((f) => !FIRST.includes(f))];

const missing = FIRST.filter((f) => !all.includes(f));
if (missing.length) {
  console.error(`build-bundle: expected sheet(s) missing: ${missing.join(', ')}`);
  process.exit(1);
}

const parts = [];
for (const f of order) {
  const css = readFileSync(join(V2, f), 'utf8');
  // A sheet that grew an @import/@charset/@layer would break the "source order
  // is the whole cascade" assumption above, so refuse rather than ship a
  // bundle that renders differently from the sheets it was built from.
  const hazard = css.match(/^\s*@(import|charset|layer)\b/m);
  if (hazard) {
    console.error(`build-bundle: ${f} contains ${hazard[0].trim()} -- concatenation is no longer order-equivalent. Fix the sheet or teach this script how to hoist it.`);
    process.exit(1);
  }
  parts.push(`/* ===== ${f} ===== */\n${css.trimEnd()}\n`);
}

const banner = `/*! CCD Design System v2 -- bundle.css
 *  GENERATED by v2/build-bundle.mjs. Do not edit; edit the source sheets.
 *  Contains, in cascade order: ${order.join(', ')}
 *  Relative asset URLs resolve from this directory, so this file must stay in v2/.
 */\n`;

const built = banner + parts.join('\n');
const current = (() => { try { return readFileSync(join(V2, OUT), 'utf8'); } catch { return null; } })();

if (process.argv.includes('--check')) {
  if (current !== built) {
    console.error(`build-bundle: ${OUT} is STALE. Run: node v2/build-bundle.mjs`);
    process.exit(1);
  }
  console.log(`build-bundle: ${OUT} is current (${order.length} sheets).`);
  process.exit(0);
}

writeFileSync(join(V2, OUT), built);
console.log(`build-bundle: wrote ${OUT} -- ${order.length} sheets, ${(built.length / 1024).toFixed(1)} kB.`);
